/**
 * Official MHD Košice route network — DPMK "Trasovanie liniek MHD, platné od 1. 7. 2026".
 * Source: https://www.dpmk.sk/cestovanie  (sections A/B/C — električkové, autobusové, nočné linky).
 *
 * Transcribed from the published route sheet: line numbers, direction headsigns and the
 * per-direction stop sequences are taken verbatim from DPMK. Coordinates come from the
 * DPMK / Ubian departure-board API (dpmk-odchody.ubian.sk), matched by stop name — a few
 * freight-only sidings have no public coordinate and carry `null`. See
 * docs/TRANSPORT-DATA-SOURCE.md for the method and known gaps.
 *
 * This is the authoritative static dataset. `data/routes.ts` and `data/stops.ts` are thin
 * adapters over it for the existing UI types; the live Ubian feed (services/ubianService.ts)
 * is untouched and still provides real-time vehicles / departures / delays.
 */

export type DpmkTransportType = 'tram' | 'bus' | 'night';

export interface DpmkNetworkStop {
  /** Stable slug id, unique across the network. */
  id: string;
  /** Official DPMK stop name. */
  name: string;
  /** Other spellings / parenthetical names DPMK uses for the same physical stop. */
  aliases?: string[];
  /** WGS84 latitude, or null when no verified coordinate is available. */
  latitude: number | null;
  longitude: number | null;
  /** Matched Ubian stop id ("u…"), or null when unmatched. */
  ubianStopId: string | null;
  /** Line numbers that call at this stop. */
  lines: string[];
}

export interface DpmkDirectionStop {
  id: string;
  name: string;
  /** 1-based position within this direction. */
  sequence: number;
  latitude: number | null;
  longitude: number | null;
}

export interface DpmkDirection {
  id: string;
  /** Display headsign — the direction's final stop (proper-cased). */
  name: string;
  /** Same as `name`: the terminus stop this direction runs to. */
  destination: string;
  /** DPMK's verbatim headsign text from the route sheet (often ALL CAPS,
   *  sometimes a district + street, e.g. "SÍDL. ŤAHANOVCE, MADRIDSKÁ"). */
  headsignRaw: string;
  stops: DpmkDirectionStop[];
}

export interface DpmkRoute {
  id: string;
  /** Public line number, e.g. "6", "R4", "23a", "52č", "N3". */
  number: string;
  name: string;
  transportType: DpmkTransportType;
  directions: DpmkDirection[];
}

