export const DPMK_STOP_BY_ID: Record<string, DpmkNetworkStop> = Object.fromEntries(
  DPMK_STOPS.map((s) => [s.id, s]),
);

export const DPMK_ROUTE_BY_NUMBER: Record<string, DpmkRoute> = Object.fromEntries(
  DPMK_ROUTES.map((r) => [r.number, r]),
);

/** Every unique stop id referenced by at least one direction. */
export const DPMK_NETWORK_STOP_IDS: string[] = [
  ...new Set(DPMK_ROUTES.flatMap((r) => r.directions.flatMap((d) => d.stops.map((s) => s.id)))),
];
